import{_ as i,o as a,c as e,a2 as o}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"附录 D：阅读路线图","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/appendix-d-reading-path.md","filePath":"chapters/appendix-d-reading-path.md"}'),r={name:"chapters/appendix-d-reading-path.md"};function t(s,l,n,d,h,p){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="附录-d-阅读路线图" tabindex="-1">附录 D：阅读路线图 <a class="header-anchor" href="#附录-d-阅读路线图" aria-label="Permalink to &quot;附录 D：阅读路线图&quot;">​</a></h1><h2 id="d-1-按角色推荐" tabindex="-1">D.1 按角色推荐 <a class="header-anchor" href="#d-1-按角色推荐" aria-label="Permalink to &quot;D.1 按角色推荐&quot;">​</a></h2><h3 id="初学者-零基础" tabindex="-1">初学者（零基础） <a class="header-anchor" href="#初学者-零基础" aria-label="Permalink to &quot;初学者（零基础）&quot;">​</a></h3><p><strong>推荐阅读顺序</strong>：</p><ol><li>第 1 章：ms-swift 是什么</li><li>第 3 章：快速入门</li><li>第 2 章：仓库全景与技术栈</li><li>第 4 章：参数系统</li><li>附录 A：超参数速查表</li></ol><p><strong>学习目标</strong>：</p><ul><li>了解 ms-swift 的基本概念</li><li>能够运行简单的训练任务</li><li>理解常用参数的含义</li></ul><hr><h3 id="算法工程师" tabindex="-1">算法工程师 <a class="header-anchor" href="#算法工程师" aria-label="Permalink to &quot;算法工程师&quot;">​</a></h3><p><strong>推荐阅读顺序</strong>：</p><ol><li>第 1-3 章：基础概念</li><li>第 12-17 章：损失函数体系</li><li>第 18-27 章：RLHF 算法</li><li>第 28-30 章：超参数详解</li><li>附录 B：损失函数速查表</li></ol><p><strong>学习目标</strong>：</p><ul><li>深入理解各种损失函数的原理和应用</li><li>掌握 RLHF 算法的选择和调优</li><li>能够根据任务选择合适的训练策略</li></ul><hr><h3 id="系统工程师" tabindex="-1">系统工程师 <a class="header-anchor" href="#系统工程师" aria-label="Permalink to &quot;系统工程师&quot;">​</a></h3><p><strong>推荐阅读顺序</strong>：</p><ol><li>第 1-3 章：基础概念</li><li>第 4-11 章：基础设施层和训练核心</li><li>第 32-34 章：分布式训练和部署</li><li>附录 A：超参数速查表</li></ol><p><strong>学习目标</strong>：</p><ul><li>理解 ms-swift 的架构设计</li><li>掌握分布式训练的配置和优化</li><li>能够部署生产级推理服务</li></ul><hr><h3 id="研究员" tabindex="-1">研究员 <a class="header-anchor" href="#研究员" aria-label="Permalink to &quot;研究员&quot;">​</a></h3><p><strong>推荐阅读顺序</strong>：</p><ol><li>第 12-17 章：损失函数体系</li><li>第 18-27 章：RLHF 算法</li><li>第 28-30 章：超参数详解</li><li>附录 B：损失函数速查表</li><li>附录 C：术语表</li></ol><p><strong>学习目标</strong>：</p><ul><li>深入理解各种算法的数学原理</li><li>能够进行算法改进和创新</li><li>理解最新研究进展</li></ul><hr><h3 id="产品经理" tabindex="-1">产品经理 <a class="header-anchor" href="#产品经理" aria-label="Permalink to &quot;产品经理&quot;">​</a></h3><p><strong>推荐阅读顺序</strong>：</p><ol><li>第 1 章：ms-swift 是什么</li><li>第 3 章：快速入门</li><li>附录 C：术语表</li><li>附录 D：阅读路线图</li></ol><p><strong>学习目标</strong>：</p><ul><li>了解 ms-swift 的功能和适用场景</li><li>理解技术术语</li><li>能够与技术团队有效沟通</li></ul><hr><h2 id="d-2-按任务推荐" tabindex="-1">D.2 按任务推荐 <a class="header-anchor" href="#d-2-按任务推荐" aria-label="Permalink to &quot;D.2 按任务推荐&quot;">​</a></h2><h3 id="sft-微调任务" tabindex="-1">SFT 微调任务 <a class="header-anchor" href="#sft-微调任务" aria-label="Permalink to &quot;SFT 微调任务&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 3 章：快速入门</li><li>第 4 章：参数系统</li><li>第 8 章：Tuner 微调方法</li><li>第 28 章：学习率与优化器</li><li>附录 A：超参数速查表</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>learning_rate</code>：full=1e-5, lora=1e-4</li><li><code>lr_scheduler_type</code>：cosine</li><li><code>tuner_type</code>：lora</li><li><code>lora_rank</code>：8</li></ul><hr><h3 id="rlhf-对齐任务" tabindex="-1">RLHF 对齐任务 <a class="header-anchor" href="#rlhf-对齐任务" aria-label="Permalink to &quot;RLHF 对齐任务&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 18 章：RLHF 概论与算法对比</li><li>第 19 章：DPO 及其 14 种变体</li><li>第 29 章：RLHF 超参数</li><li>附录 B：损失函数速查表</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>rlhf_type</code>：dpo（推荐）</li><li><code>beta</code>：DPO=0.1</li><li><code>loss_type</code>：sigmoid</li></ul><hr><h3 id="嵌入模型训练" tabindex="-1">嵌入模型训练 <a class="header-anchor" href="#嵌入模型训练" aria-label="Permalink to &quot;嵌入模型训练&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 14 章：嵌入学习损失函数</li><li>第 35 章：评估系统</li><li>附录 B：损失函数速查表</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>task_type</code>：embedding</li><li><code>loss_type</code>：infonce</li><li><code>INFONCE_TEMPERATURE</code>：0.1</li></ul><hr><h3 id="知识蒸馏任务" tabindex="-1">知识蒸馏任务 <a class="header-anchor" href="#知识蒸馏任务" aria-label="Permalink to &quot;知识蒸馏任务&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 25 章：GKD 知识蒸馏</li><li>第 30 章：GRPO 与 PPO 超参数</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>rlhf_type</code>：gkd</li><li><code>teacher_model</code>：教师模型</li><li><code>beta</code>：0.5</li></ul><hr><h3 id="大规模训练" tabindex="-1">大规模训练 <a class="header-anchor" href="#大规模训练" aria-label="Permalink to &quot;大规模训练&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 32 章：DeepSpeed 与 FSDP</li><li>第 33 章：Megatron 集成</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>deepspeed</code>：zero3_offload</li><li><code>tensor_model_parallel_size</code>：4</li><li><code>pipeline_model_parallel_size</code>：2</li></ul><hr><h3 id="模型部署" tabindex="-1">模型部署 <a class="header-anchor" href="#模型部署" aria-label="Permalink to &quot;模型部署&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 11 章：推理引擎</li><li>第 34 章：模型导出与部署</li><li>第 31 章：部署与推理超参数</li></ol><p><strong>关键参数</strong>：</p><ul><li><code>infer_backend</code>：vllm</li><li><code>tensor_parallel_size</code>：4</li><li><code>temperature</code>：0.7</li></ul><hr><h2 id="d-3-按时间推荐" tabindex="-1">D.3 按时间推荐 <a class="header-anchor" href="#d-3-按时间推荐" aria-label="Permalink to &quot;D.3 按时间推荐&quot;">​</a></h2><h3 id="_1-小时速成" tabindex="-1">1 小时速成 <a class="header-anchor" href="#_1-小时速成" aria-label="Permalink to &quot;1 小时速成&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 1 章：ms-swift 是什么（10 分钟）</li><li>第 3 章：快速入门（20 分钟）</li><li>附录 A：超参数速查表（15 分钟）</li><li>附录 C：术语表（15 分钟）</li></ol><p><strong>学习目标</strong>：</p><ul><li>了解 ms-swift 的基本功能</li><li>能够运行简单的训练任务</li></ul><hr><h3 id="_1-天入门" tabindex="-1">1 天入门 <a class="header-anchor" href="#_1-天入门" aria-label="Permalink to &quot;1 天入门&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 1-3 章：基础概念（1 小时）</li><li>第 4 章：参数系统（1 小时）</li><li>第 8 章：Tuner 微调方法（1 小时）</li><li>第 12-13 章：损失函数基础（1 小时）</li><li>附录 A：超参数速查表（30 分钟）</li><li>实践：运行一个 SFT 训练任务（2 小时）</li></ol><p><strong>学习目标</strong>：</p><ul><li>掌握 ms-swift 的核心概念</li><li>能够独立进行 SFT 训练</li><li>理解常用参数的含义</li></ul><hr><h3 id="_1-周深入" tabindex="-1">1 周深入 <a class="header-anchor" href="#_1-周深入" aria-label="Permalink to &quot;1 周深入&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>第 1-11 章：基础设施和训练核心（2 天）</li><li>第 12-17 章：损失函数体系（1 天）</li><li>第 18-27 章：RLHF 算法（2 天）</li><li>第 28-30 章：超参数详解（1 天）</li><li>第 32-35 章：高级主题（1 天）</li><li>实践：完成一个完整的 RLHF 训练流程（1 天）</li></ol><p><strong>学习目标</strong>：</p><ul><li>深入理解 ms-swift 的所有核心模块</li><li>能够进行 RLHF 训练和调优</li><li>理解各种损失函数的原理和应用</li></ul><hr><h3 id="_1-个月精通" tabindex="-1">1 个月精通 <a class="header-anchor" href="#_1-个月精通" aria-label="Permalink to &quot;1 个月精通&quot;">​</a></h3><p><strong>推荐阅读</strong>：</p><ol><li>全部 35 章 + 4 个附录（2 周）</li><li>阅读源码：swift/loss/, swift/rlhf_trainers/（1 周）</li><li>实践：完成多个项目（1 周）</li></ol><p><strong>学习目标</strong>：</p><ul><li>完全掌握 ms-swift 的架构设计</li><li>能够进行算法改进和创新</li><li>能够解决复杂的训练问题</li></ul><hr><h2 id="d-4-常见问题" tabindex="-1">D.4 常见问题 <a class="header-anchor" href="#d-4-常见问题" aria-label="Permalink to &quot;D.4 常见问题&quot;">​</a></h2><h3 id="q-我应该先学-sft-还是-rlhf" tabindex="-1">Q: 我应该先学 SFT 还是 RLHF？ <a class="header-anchor" href="#q-我应该先学-sft-还是-rlhf" aria-label="Permalink to &quot;Q: 我应该先学 SFT 还是 RLHF？&quot;">​</a></h3><p><strong>A</strong>: 建议先学 SFT。SFT 是基础，RLHF 是在 SFT 基础上的对齐训练。掌握 SFT 后再学习 RLHF 会更容易理解。</p><h3 id="q-我需要读懂所有源码吗" tabindex="-1">Q: 我需要读懂所有源码吗？ <a class="header-anchor" href="#q-我需要读懂所有源码吗" aria-label="Permalink to &quot;Q: 我需要读懂所有源码吗？&quot;">​</a></h3><p><strong>A</strong>: 不需要。根据你的角色和目标，选择性阅读相关章节。初学者只需要理解参数配置和使用方法，算法工程师需要深入理解损失函数和 RLHF 算法。</p><h3 id="q-如何选择合适的-rlhf-算法" tabindex="-1">Q: 如何选择合适的 RLHF 算法？ <a class="header-anchor" href="#q-如何选择合适的-rlhf-算法" aria-label="Permalink to &quot;Q: 如何选择合适的 RLHF 算法？&quot;">​</a></h3><p><strong>A</strong>:</p><ul><li>初学者：使用 DPO（最稳定）</li><li>资源有限：使用 CPO/SimPO（无需参考模型）</li><li>追求效果：使用 PPO/GRPO（在线学习）</li><li>数据格式限制：根据数据选择（成对数据用 DPO，二元数据用 KTO）</li></ul><h3 id="q-学习过程中遇到问题怎么办" tabindex="-1">Q: 学习过程中遇到问题怎么办？ <a class="header-anchor" href="#q-学习过程中遇到问题怎么办" aria-label="Permalink to &quot;Q: 学习过程中遇到问题怎么办？&quot;">​</a></h3><p><strong>A</strong>:</p><ol><li>查阅附录 C：术语表</li><li>查阅附录 A：超参数速查表</li><li>查看 ms-swift 官方文档</li><li>查看 ms-swift GitHub Issues</li><li>在社区提问</li></ol>',105)])])}const g=i(r,[["render",t]]);export{u as __pageData,g as default};
